def from_robot=ctx.curReq[0].fromRobot()
if (from_robot) {
    return 'from_robot_test1'
} else {
    return 'from_user_test1'
}

import com.jd.security.llmsec.core.check.MixedCheck
def retMap=ctx.curResult.resultMap
def next="from_user_test_bert2"
def kw = retMap.keyword
def fast = retMap.fast20250710

if (kw != null && (kw.bwgLabel == 1 || kw.bwgLabel == 2 )){
    ctx.curResult = kw
    return null
} else if (kw != null && kw.bwgLabel == 3){
    return next
} else if (fast != null) {
    if (!fast.hasRisk() && fast.probability > 0.9) {
      ctx.curResult = fast
      return null
    } else {
      return next
    }
}
if (kw == null || fast == null) {
  ctx.curResult = MixedCheck.noRisk()
  return null
}
return next

import com.jd.security.llmsec.core.check.MixedCheck
def retMap = ctx.curResult.resultMap
def bert_common = retMap.bert_20250916
def bert_inject = retMap.bert_prompt_injection_20250828

def thresholds_common = [0:0.85, 1001:0.85, 1002:0.85, 1003:0.85, 1004:0.85, 1005:0.85, 1006:0.85, 1007:0.85, 2001:0.85, 3002:0.85, 4002:0.85, 5001:0.85, 5002:0.85]
def thresholds_inject = [0:0.85, 201:0.85]

// OR 逻辑：任一模型触发即拦截，修复原有 null 未检查导致的 NPE 风险
// 防御 OTTER：攻击者需同时骗过两个独立 BERT 模型
def common_risk = bert_common != null && bert_common.hasRisk() \
    && thresholds_common.containsKey(bert_common.riskCode) \
    && bert_common.probability >= thresholds_common[bert_common.riskCode]
def inject_risk = bert_inject != null && bert_inject.hasRisk() \
    && thresholds_inject.containsKey(bert_inject.riskCode) \
    && bert_inject.probability >= thresholds_inject[bert_inject.riskCode]

if (common_risk) {
  ctx.curResult = bert_common
  return null
} else if (inject_risk) {
  ctx.curResult = bert_inject
  return null
} else {
  ctx.curResult = MixedCheck.noRisk()
  return 'from_user_test3_intent'
}

import com.jd.security.llmsec.core.check.RiskCheckType
import com.jd.security.llmsec.core.check.MixedCheck

def intent_results = ctx.middleResults[RiskCheckType.intent_check]
if (intent_results == null || intent_results.isEmpty()) {
  return null
}
def intent = intent_results[0]
if (intent.hasRisk()) {
  if (intent.protoRiskCode != null) {
    intent.setRiskCode(intent.protoRiskCode)
  }
  ctx.curResult = intent
}
return null

def req = ctx.curReq[0]
// 只有带附件的请求才经过多模态抽取，纯文本请求零额外开销
if (req.hasAttachments()) {
    return 'media_extract'
}
return 'keyword_check'

def me = ctx.curResult
if (me != null && me.hasRisk()) {
    return null
}
return 'keyword_check'

def kw = ctx.curResult
// 黑名单命中直接结束；其余交给安全模型
if (kw != null && kw.hasRisk()) {
    return null
}
return 'mm_guard'

def guard = ctx.curResult
// 安全模型调用失败（超时/服务不可用）时整条交给裁判兜底
if (guard == null) {
    return 'llm_judge'
}
// 置信度低于阈值 / 争议类 / 拿不到置信度 -> 升级；否则以第一层结论结束
return guard.escalate ? 'llm_judge' : null

def from_robot=ctx.curReq[0].fromRobot()
if (from_robot) {
    return 'from_robot1'
} else {
    return 'from_user1'
}

import com.jd.security.llmsec.core.check.RiskCheckType
import com.jd.security.llmsec.core.check.MixedCheck

def rag_answers = ctx.middleResults[RiskCheckType.rag_answer]
if (rag_answers != null && rag_answers[0].riskCode > 0) {
  rag_answer = rag_answers[0]
  ctx.curResult = rag_answer
  return null
}

def bert = null
def fast=null
def single_label_results = ctx.middleResults[RiskCheckType.single_label_pred]

//取fast结果
if (single_label_results != null) {
    for (item in single_label_results) {
        if (item.srcName.contains("fast20250710")) {
            fast = item
        }
        if (item.srcName.contains("bert_20250916")) {
            bert = item
        }
    }
}

// OR 逻辑：任意模型置信度足够高即拦截
// 防御 OTTER 类攻击：攻击者必须同时骗过所有模型才能绕过
if (bert != null && bert.hasRisk() && bert.probability > 0.7) {
    ctx.curResult = bert
    return null
} else if (fast != null && fast.hasRisk() && fast.probability > 0.7) {
    ctx.curResult = fast
    return null
} else {
    ctx.curResult = MixedCheck.noRisk()
    return 'from_user3_intent'
}

import com.jd.security.llmsec.core.check.RiskCheckType
import com.jd.security.llmsec.core.check.MixedCheck

def intent_results = ctx.middleResults[RiskCheckType.intent_check]
if (intent_results == null || intent_results.isEmpty()) {
  // intent 服务不可用，沿用上一层结果
  return null
}
def intent = intent_results[0]
if (intent.hasRisk()) {
  // 语义意图命中：即使表面 token 已被替换，意图向量仍在原型附近
  // 将原型 risk_code 透传以保持风险分类一致性
  if (intent.protoRiskCode != null) {
    intent.setRiskCode(intent.protoRiskCode)
  }
  ctx.curResult = intent
}
// 无命中：维持 BERT 层已有的 noRisk 判断
return null

def req = ctx.curReq[0]
if (req.fromRobot()) {
    return 'from_robot_test1'
}
// 只有带附件的请求才经过多模态节点，纯文本请求零额外开销
return req.hasAttachments() ? 'from_user_media' : 'from_user_test1'

def me = ctx.curResult
if (me != null && me.hasRisk()) {
    // 抽取失败（fail-closed），直接以 1100 结束
    return null
}
// 抽取出的文字已追加到 ctx.checkContent，继续走文本检测链路
return 'from_user_test1'

import com.jd.security.llmsec.core.check.MixedCheck
def retMap=ctx.curResult.resultMap
def kw = retMap.keyword

if (kw != null && (kw.bwgLabel == 1 || kw.bwgLabel == 2 )){
    ctx.curResult = kw
    return null
} else {
    return 'from_user_test_bert2'
}

import com.jd.security.llmsec.core.check.MixedCheck
def retMap = ctx.curResult.resultMap
def bert_inject = retMap.bert_prompt_injection_20250828

def thresholds_inject = [0:0.85, 201:0.85]

def inject_risk = bert_inject != null && bert_inject.hasRisk() \
    && thresholds_inject.containsKey(bert_inject.riskCode) \
    && bert_inject.probability >= thresholds_inject[bert_inject.riskCode]

if (inject_risk) {
  ctx.curResult = bert_inject
} else {
  ctx.curResult = MixedCheck.noRisk()
}
return null
